var t=[{title:`Wat je vermindert`,text:`De eenvoudigste aanpak is om gedurende enkele trainingen minder zware sets te doen en verder van falen te blijven. Doe je gewoonlijk vier sets per oefening, dan kun je bijvoorbeeld een week lang twee lichte sets per oefening doen. Het volume met ongeveer 40–50% verminderen is een praktische optie. De wetenschap geeft geen exact percentage.`},{title:`Houd wat trainingsprikkel vast`,text:`Een deload kan nog steeds training bevatten. Vertrouwde oefeningen met een lagere inspanning doen houdt je coördinatie en routine op gang. Sommige tillers houden matige gewichten aan en doen minder sets. Anderen verlagen zowel gewicht als sets als hun gewrichten of algemene vermoeidheid de zorg zijn. De beste keuze hangt af van waarom je de deload nodig hebt.`},{title:`Wanneer het helpt`,text:`Waarschuwingssignalen kunnen zijn: meerdere ongewoon zware trainingen, dalende prestaties, vermoeidheid die niet weggaat of een groeiend gevoel dat je niet herstelt. Deze signalen kunnen veel oorzaken hebben. Schrijf ziekte of medische klachten niet af als normale trainingsvermoeidheid. Ben je nieuw met trainen, dan heb je misschien gewoon een rustiger regulier schema nodig, zonder geplande deloads.`},{title:`Gepland of indien nodig`,text:`Sommige gestructureerde programma’s gebruiken om de vier tot acht weken een lichtere week, vooral bij een hoge werkbelasting. Die timing is één manier om het te organiseren. Gaat een matig programma goed voor je, dan heb je misschien geen formele deload nodig, en bij ongewone stress kan een eerdere helpen.`},{title:`TrainUp gebruiken`,text:`Week 4 van elk TrainUp-schema is een lichtere deloadweek. Als je je schema opnieuw maakt, wordt het lichter als 2 van je laatste 3 trainingen zeer zwaar waren (RPE 9 of hoger) of voor minder dan 60% zijn afgerond. Keer na een lichtere periode stap voor stap terug naar normale gewichten en let op hoe je reageert. Een week rust garandeert niet dat je sterker terugkomt.`}];var i=[{label:`Standpunt van het ACSM uit 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NSCA: basis van veiligheid en krachttraining`,url:`https://www.nsca.com/education/articles/ptq/the-safest-and-riskiest-forms-of-resistance-training/`},{label:`Systematisch overzicht van periodisering en trainingsresultaten`,url:`https://pubmed.ncbi.nlm.nih.gov/35044672/`}];var a={sections:t,sources:i};export{a as default,t as sections,i as sources};